<template>
  <div class="form">
    <div class="form-group">
      <div class="form-input">
        <i class="fas fa-user"></i>
        <input v-model="username" type="text" autocomplete='off' spellcheck='false' autocorrect='off'
               placeholder="Username">
      </div>
    </div>
    <div class="form-group">
      <div class="form-input">
        <i class="fas fa-lock"></i>
        <input v-model="password" type="password" autocomplete='off' spellcheck='false' autocorrect='off'
               placeholder="Password">
      </div>
    </div>
    <button class="form-button" @click="submit" :disabled="loading" ><i v-if="loading" class="fas fa-spinner fa-spin"></i> Login</button>
  </div>
  <div class="ask">
    Don't have an account? <strong style="cursor: pointer;" @click='$emit("toggle", false)'>Register</strong>
  </div>
</template>

<script>

export default {
  name: "Login",
  emits: ['toggle'],
  methods: {
    submit() {
      this.loading = true;
      setTimeout(() => { this.loading = false; this.password = ""; }, 1000);

      // eslint-disable-next-line no-undef
      mp.trigger('loginInformationToServer', this.username, this.password);

    }
  },
  data() {
    return {
      username: "",
      password: "",
      loading: false
    }
  },
}
</script>

<style scoped lang="scss">
@import '~@/assets/form.scss';
</style>